import React, { useState, useEffect } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import { useQuery, useMutation } from '@tanstack/react-query';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { motion, AnimatePresence } from 'framer-motion';
import { Package, ShoppingCart, Truck, CreditCard, Check, ArrowRight, MapPin, Phone, Mail, User } from 'lucide-react';
import toast from 'react-hot-toast';
import productService from '../../services/productService';
import api from '../../services/api';
import ValidatedInput from '../../components/forms/ValidatedInput';
import StatusBadge from '../../components/datadisplay/StatusBadge';

const orderSchema = z.object({
    quantity: z.string().min(1, 'Quantity is required').transform(Number).pipe(
        z.number().int().min(1, 'Must be at least 1')
    ),
    paymentMethod: z.enum(['online', 'delivery'], {
        errorMap: () => ({ message: 'Please select a payment method' })
    }),
    customer: z.object({
        firstName: z.string().min(2, 'First name is required'),
        lastName: z.string().min(2, 'Last name is required'),
        email: z.string().email('Valid email is required'),
        phone: z.string().min(10, 'Valid phone number is required'),
        address: z.string().min(5, 'Address is required'),
        city: z.string().min(2, 'City is required'),
        state: z.string().min(2, 'State is required')
    }),
    notes: z.string().optional()
});

const OrderPage = () => {
    const { productId } = useParams();
    const [searchParams] = useSearchParams();
    const [step, setStep] = useState(1);
    const [orderComplete, setOrderComplete] = useState(false);

    const { register, handleSubmit, watch, formState: { errors } } = useForm({
        resolver: zodResolver(orderSchema),
        defaultValues: {
            quantity: '1',
            paymentMethod: 'delivery',
            customer: {
                firstName: '',
                lastName: '',
                email: '',
                phone: '',
                address: '',
                city: '',
                state: ''
            },
            notes: ''
        }
    });

    const { data: product, isLoading } = useQuery({
        queryKey: ['product', productId],
        queryFn: () => productService.getProduct(productId),
        enabled: !!productId
    });

    const orderMutation = useMutation({
        mutationFn: (orderData) => api.post('/orders', orderData),
        onSuccess: () => {
            setOrderComplete(true);
            setStep(3);
            toast.success('Order placed successfully!');
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Failed to place order');
        }
    });

    const watchQuantity = watch('quantity');
    const watchPaymentMethod = watch('paymentMethod');

    const total = product ? product.price * (parseInt(watchQuantity) || 1) : 0;

    const onSubmit = (data) => {
        const orderData = {
            productId,
            quantity: parseInt(data.quantity),
            paymentMethod: data.paymentMethod,
            customer: data.customer,
            notes: data.notes,
            utm_source: searchParams.get('utm_source'),
            utm_medium: searchParams.get('utm_medium'),
            utm_campaign: searchParams.get('utm_campaign')
        };

        if (data.paymentMethod === 'online') {
            // Handle online payment here (we'll integrate payment gateway later)
            toast.success('Redirecting to payment...');
        }

        orderMutation.mutate(orderData);
    };

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center">
                <div className="w-8 h-8 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin" />
            </div>
        );
    }

    if (orderComplete) {
        return <OrderSuccess />;
    }

    return (
        <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-teal-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900">
            {/* Header */}
            <div className="bg-white dark:bg-gray-800 shadow-sm border-b border-gray-200 dark:border-gray-700">
                <div className="max-w-4xl mx-auto px-4 py-4">
                    <div className="flex items-center gap-3">
                        <Package className="h-8 w-8 text-indigo-600" />
                        <h1 className="text-xl font-bold text-gray-900 dark:text-white">Place Your Order</h1>
                    </div>
                </div>
            </div>

            <div className="max-w-4xl mx-auto px-4 py-8">
                {/* Progress Steps */}
                <div className="mb-8">
                    <div className="flex items-center justify-center gap-4">
                        {['Product', 'Details', 'Confirmation'].map((label, index) => (
                            <div key={label} className="flex items-center gap-2">
                                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${step > index + 1
                                        ? 'bg-emerald-500 text-white'
                                        : step === index + 1
                                            ? 'bg-indigo-600 text-white'
                                            : 'bg-gray-200 text-gray-500'
                                    }`}>
                                    {step > index + 1 ? <Check className="h-4 w-4" /> : index + 1}
                                </div>
                                <span className={`text-sm font-medium hidden sm:block ${step === index + 1 ? 'text-indigo-600' : 'text-gray-500'
                                    }`}>
                                    {label}
                                </span>
                                {index < 2 && <div className="w-12 h-0.5 bg-gray-200 hidden sm:block" />}
                            </div>
                        ))}
                    </div>
                </div>

                <AnimatePresence mode="wait">
                    {step === 1 && (
                        <motion.div
                            key="step1"
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: 20 }}
                        >
                            {/* Product Preview */}
                            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-6 mb-6">
                                <div className="flex flex-col sm:flex-row gap-6">
                                    <div className="w-full sm:w-48 h-48 rounded-xl bg-gray-100 dark:bg-gray-700 overflow-hidden flex-shrink-0">
                                        {product.imageUrl ? (
                                            <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center">
                                                <Package className="h-16 w-16 text-gray-400" />
                                            </div>
                                        )}
                                    </div>

                                    <div className="flex-1">
                                        <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
                                            {product.name}
                                        </h2>
                                        <p className="text-gray-500 dark:text-gray-400 mb-4">
                                            {product.description}
                                        </p>

                                        <div className="flex items-center gap-4 mb-4">
                                            <span className="text-3xl font-bold text-indigo-600">
                                                ${product.price.toFixed(2)}
                                            </span>
                                            <StatusBadge status={product.stockStatus.status} label={product.stockStatus.label} />
                                        </div>

                                        <div className="space-y-4">
                                            <div>
                                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                                                    Quantity
                                                </label>
                                                <select
                                                    {...register('quantity')}
                                                    className="block w-32 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                                                >
                                                    {Array.from({ length: Math.min(10, product.quantity) }, (_, i) => i + 1).map(num => (
                                                        <option key={num} value={num}>{num}</option>
                                                    ))}
                                                </select>
                                            </div>

                                            <div className="p-4 bg-gray-50 dark:bg-gray-900 rounded-lg">
                                                <div className="flex justify-between items-center">
                                                    <span className="text-lg font-semibold text-gray-900 dark:text-white">Total:</span>
                                                    <span className="text-2xl font-bold text-indigo-600">${total.toFixed(2)}</span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <button
                                onClick={() => setStep(2)}
                                className="w-full flex items-center justify-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-medium transition-colors"
                            >
                                Continue to Details
                                <ArrowRight className="h-5 w-5" />
                            </button>
                        </motion.div>
                    )}

                    {step === 2 && (
                        <motion.div
                            key="step2"
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                        >
                            <form onSubmit={handleSubmit(() => setStep(3))}>
                                <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-6 space-y-6">
                                    <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                                        <User className="h-6 w-6 text-indigo-600" />
                                        Customer Information
                                    </h2>

                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                        <ValidatedInput
                                            label="First Name"
                                            required
                                            error={errors.customer?.firstName?.message}
                                            {...register('customer.firstName')}
                                        />
                                        <ValidatedInput
                                            label="Last Name"
                                            required
                                            error={errors.customer?.lastName?.message}
                                            {...register('customer.lastName')}
                                        />
                                    </div>

                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                        <ValidatedInput
                                            label="Email"
                                            type="email"
                                            icon={Mail}
                                            required
                                            error={errors.customer?.email?.message}
                                            {...register('customer.email')}
                                        />
                                        <ValidatedInput
                                            label="Phone"
                                            type="tel"
                                            icon={Phone}
                                            required
                                            error={errors.customer?.phone?.message}
                                            {...register('customer.phone')}
                                        />
                                    </div>

                                    <ValidatedInput
                                        label="Delivery Address"
                                        icon={MapPin}
                                        required
                                        error={errors.customer?.address?.message}
                                        {...register('customer.address')}
                                    />

                                    <div className="grid grid-cols-2 gap-4">
                                        <ValidatedInput
                                            label="City"
                                            required
                                            error={errors.customer?.city?.message}
                                            {...register('customer.city')}
                                        />
                                        <ValidatedInput
                                            label="State"
                                            required
                                            error={errors.customer?.state?.message}
                                            {...register('customer.state')}
                                        />
                                    </div>

                                    {/* Payment Method */}
                                    <div>
                                        <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2 mb-4">
                                            <CreditCard className="h-6 w-6 text-indigo-600" />
                                            Payment Method
                                        </h2>

                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                            <label className={`relative flex items-center gap-3 p-4 rounded-xl border-2 cursor-pointer transition-all ${watchPaymentMethod === 'online'
                                                    ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20'
                                                    : 'border-gray-200 hover:border-gray-300'
                                                }`}>
                                                <input
                                                    type="radio"
                                                    value="online"
                                                    {...register('paymentMethod')}
                                                    className="sr-only"
                                                />
                                                <CreditCard className="h-8 w-8 text-indigo-600" />
                                                <div>
                                                    <p className="font-medium text-gray-900 dark:text-white">Pay Online</p>
                                                    <p className="text-sm text-gray-500">Credit/Debit Card, Bank Transfer</p>
                                                </div>
                                            </label>

                                            <label className={`relative flex items-center gap-3 p-4 rounded-xl border-2 cursor-pointer transition-all ${watchPaymentMethod === 'delivery'
                                                    ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20'
                                                    : 'border-gray-200 hover:border-gray-300'
                                                }`}>
                                                <input
                                                    type="radio"
                                                    value="delivery"
                                                    {...register('paymentMethod')}
                                                    className="sr-only"
                                                />
                                                <Truck className="h-8 w-8 text-emerald-600" />
                                                <div>
                                                    <p className="font-medium text-gray-900 dark:text-white">Pay on Delivery</p>
                                                    <p className="text-sm text-gray-500">Cash or card on delivery</p>
                                                </div>
                                            </label>
                                        </div>
                                    </div>

                                    {/* Notes */}
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                                            Order Notes (Optional)
                                        </label>
                                        <textarea
                                            {...register('notes')}
                                            rows={3}
                                            className="block w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
                                            placeholder="Any special instructions..."
                                        />
                                    </div>
                                </div>

                                <div className="flex gap-3 mt-6">
                                    <button
                                        type="button"
                                        onClick={() => setStep(1)}
                                        className="flex-1 px-6 py-3 border border-gray-300 text-gray-700 rounded-xl font-medium hover:bg-gray-50 transition-colors"
                                    >
                                        Back
                                    </button>
                                    <button
                                        type="submit"
                                        className="flex-1 px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-medium transition-colors"
                                    >
                                        Review Order
                                    </button>
                                </div>
                            </form>
                        </motion.div>
                    )}

                    {step === 3 && (
                        <motion.div
                            key="step3"
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                        >
                            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-6">
                                <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6">Order Summary</h2>

                                {/* Product Summary */}
                                <div className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-gray-900 rounded-lg mb-4">
                                    <div className="h-16 w-16 rounded-lg bg-gray-200 overflow-hidden">
                                        {product.imageUrl && <img src={product.imageUrl} alt={product.name} className="h-full w-full object-cover" />}
                                    </div>
                                    <div>
                                        <p className="font-medium text-gray-900 dark:text-white">{product.name}</p>
                                        <p className="text-sm text-gray-500">Qty: {watchQuantity}</p>
                                    </div>
                                    <p className="ml-auto font-bold text-gray-900 dark:text-white">${total.toFixed(2)}</p>
                                </div>

                                {/* Payment Method */}
                                <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-gray-900 rounded-lg mb-4">
                                    {watchPaymentMethod === 'online' ? (
                                        <CreditCard className="h-5 w-5 text-indigo-600" />
                                    ) : (
                                        <Truck className="h-5 w-5 text-emerald-600" />
                                    )}
                                    <span className="text-gray-700 dark:text-gray-300">
                                        {watchPaymentMethod === 'online' ? 'Online Payment' : 'Pay on Delivery'}
                                    </span>
                                </div>

                                {/* Total */}
                                <div className="border-t border-gray-200 dark:border-gray-700 pt-4">
                                    <div className="flex justify-between items-center">
                                        <span className="text-lg font-bold text-gray-900 dark:text-white">Total Amount</span>
                                        <span className="text-2xl font-bold text-indigo-600">${total.toFixed(2)}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-3 mt-6">
                                <button
                                    onClick={() => setStep(2)}
                                    className="flex-1 px-6 py-3 border border-gray-300 text-gray-700 rounded-xl font-medium hover:bg-gray-50 transition-colors"
                                >
                                    Back
                                </button>
                                <button
                                    onClick={handleSubmit(onSubmit)}
                                    disabled={orderMutation.isLoading}
                                    className="flex-1 flex items-center justify-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-medium transition-colors disabled:opacity-50"
                                >
                                    {orderMutation.isLoading ? (
                                        <>
                                            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                            Placing Order...
                                        </>
                                    ) : (
                                        <>
                                            <ShoppingCart className="h-5 w-5" />
                                            Place Order
                                        </>
                                    )}
                                </button>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
};

const OrderSuccess = () => (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-indigo-50 via-white to-teal-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900">
        <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: 'spring', stiffness: 200 }}
            className="text-center"
        >
            <div className="inline-flex items-center justify-center w-24 h-24 rounded-full bg-emerald-100 dark:bg-emerald-900/30 mb-6">
                <Check className="h-12 w-12 text-emerald-600" />
            </div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">Order Placed Successfully!</h1>
            <p className="text-gray-500 dark:text-gray-400 mb-6">Thank you for your order. We'll contact you shortly.</p>
            <p className="text-sm text-gray-400">A sales representative will process your order soon.</p>
        </motion.div>
    </div>
);

export default OrderPage;
